from pathlib import Path
sys.path.insert(0,str(Path('scripts').resolve()))
from privacy import has_local_identifier
violations=[]
for name in subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard'],text=True,encoding='utf-8').splitlines():
    p=Path(name)
    if p.suffix.lower() in ['.jpg','.jpeg','.png']: continue
    try: value=p.read_text(encoding='utf-8')
    except (UnicodeDecodeError,FileNotFoundError): continue
    if has_local_identifier(value) or re.search(r'sk-[A-Za-z0-9_-]{16,}',value):violations.append(name)
    if p.suffix=='.json':json.loads(value)
    if p.suffix=='.jsonl':
        for line in value.splitlines():json.loads(line)
print({'public_identifier_files':violations,'public_structured_files_valid':True,'private_configuration_ignored':subprocess.run(['git','check-ignore','-q','backend/.env','.env.local']).returncode==0})
if violations:raise SystemExit(1)
